// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    function setUp() public { c = new L1Block(); }
    function testFuzz_property(uint256 seed) public {
        // drive c through the public pure entry `version`; no state setup needed
        string memory v = c.version();
        assertTrue(keccak256(bytes(v)) == keccak256(bytes("1.0.0")), "version must be 1.0.0");
        // seed only keeps the fuzzer's input space wide; the rule above is universal
    }
}
